cd /tmp && python3 -c "
import pandas as pd
try:
    df = pd.read_excel('/tmp/budget.xlsx')
    print(df.to_string())
    print()
    print('Columns:', list(df.columns))
except FileNotFoundError:
    import os
    for root, dirs, files in os.walk('/'):
        if 'budget.xlsx' in files:
            print(os.path.join(root, 'budget.xlsx'))
